const fs = require('fs');
const path = require('path');
const emulatorUtil = require('@aiot-toolkit/emulator/lib/emulatorutil');
const { createGrpcClient } = require('@aiot-toolkit/emulator/lib/vvd/grpc');

const VVD_NAME = 'Vela_Official_Watch_5_Demo';
const FPS = 10;
const DURATION_SECONDS = 60;
const outputDirectory = path.resolve(process.argv[2] || 'output/video/final-frames');

const wait = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds));

async function click(client, x, y) {
  client.sendMouse({ x, y, buttons: 1 });
  await wait(55);
  client.sendMouse({ x, y, buttons: 0 });
}

async function setAcceleration(client, data) {
  await new Promise((resolve, reject) => {
    client.client.setSensor(
      { target: 'ACCELERATION', value: { data } },
      client.authMate,
      (error) => (error ? reject(error) : resolve()),
    );
  });
}

async function main() {
  const running = emulatorUtil.getRunningAvdConfigByName(VVD_NAME);
  if (!running) throw new Error(`${VVD_NAME} is not running`);

  fs.mkdirSync(outputDirectory, { recursive: true });
  const client = createGrpcClient(running);
  await client.waitForReady();

  let latestFrame = await client.getScreenshot();
  await client.startStream((frame) => {
    latestFrame = frame;
  });

  const startTime = Date.now();
  const events = [
    [6000, () => click(client, 145, 360)],
    [21000, () => click(client, 233, 430)],
    [25000, () => click(client, 320, 360)],
    [25300, () => setAcceleration(client, [0, 0, 9.8])],
  ];
  let highAcceleration = true;
  for (let t = 25950; t <= 33950; t += 1000) {
    const data = highAcceleration ? [10, 0, 9.8] : [0, 0, 9.8];
    events.push([t, () => setAcceleration(client, data)]);
    highAcceleration = !highAcceleration;
  }
  events.sort((a, b) => a[0] - b[0]);

  let nextEvent = 0;
  for (let frameNumber = 0; frameNumber < FPS * DURATION_SECONDS; frameNumber += 1) {
    const targetTime = frameNumber * (1000 / FPS);
    while (nextEvent < events.length && events[nextEvent][0] <= targetTime) {
      await events[nextEvent][1]();
      nextEvent += 1;
    }
    const framePath = path.join(
      outputDirectory,
      `frame-${String(frameNumber + 1).padStart(4, '0')}.png`,
    );
    fs.writeFileSync(framePath, latestFrame);
    const remaining = startTime + targetTime + 1000 / FPS - Date.now();
    if (remaining > 0) await wait(remaining);
  }

  client.close();
  console.log(JSON.stringify({ outputDirectory, frames: FPS * DURATION_SECONDS, fps: FPS }));
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

