+const fs = require('fs');
+const path = require('path');
+const emulatorUtil = require('@aiot-toolkit/emulator/lib/emulatorutil');
+const { findInstance } = require('@aiot-toolkit/emulator/lib/instance');
+const { createGrpcClient } = require('@aiot-toolkit/emulator/lib/vvd/grpc');
+
+const VVD_NAME = 'Vela_Official_Watch_5_Demo';
+const IMAGE_TYPE = 'vela-miwear-watch-5.0';
+const PACKAGE_NAME = 'com.openvela.wristrhythm';
+const FPS = 10;
+const DURATION_SECONDS = 111;
+const FRAME_COUNT = FPS * DURATION_SECONDS;
+const PROJECT_ROOT = path.resolve(__dirname, '..');
+const OUTPUT_ROOT = path.join(PROJECT_ROOT, 'output', 'video', 'official-health-demo-v2');
+const MANIFEST_PATH = path.join(OUTPUT_ROOT, 'capture-manifest.json');
+
+const UI_EVENTS = [
+  { at: 8000, kind: 'click', x: 145, y: 360, label: 'start-steady' },
+  { at: 74000, kind: 'click', x: 233, y: 360, label: 'return-home' },
+  { at: 76000, kind: 'click', x: 320, y: 360, label: 'start-boxing' },
+  { at: 76300, kind: 'acceleration', data: [0, 0, 9.8], label: 'motion-ready' },
+];
+
+let highAcceleration = true;
+for (let at = 76950; at <= 105950; at += 1000) {
+  UI_EVENTS.push({
+    at,
+    kind: 'acceleration',
+    data: highAcceleration ? [10, 0, 9.8] : [0, 0, 9.8],
+    label: `motion-${(at - 76950) / 1000 + 1}`,
+  });
+  highAcceleration = !highAcceleration;
+}
+
+const wait = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds));
+
+function assertOutputDirectorySafe(directory) {
+  const resolvedDirectory = path.resolve(directory);
+  const relativePath = path.relative(OUTPUT_ROOT, resolvedDirectory);
+  if (!relativePath || relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
+    throw new Error(`Unsafe frame output directory: ${resolvedDirectory}`);
+  }
+  return resolvedDirectory;
+}
+
+function timestampForDirectory(date = new Date()) {
+  const twoDigits = (value) => String(value).padStart(2, '0');
+  return `${date.getFullYear()}${twoDigits(date.getMonth() + 1)}${twoDigits(date.getDate())}`
+    + `-${twoDigits(date.getHours())}${twoDigits(date.getMinutes())}${twoDigits(date.getSeconds())}`;
+}
+
+function createFreshFrameDirectory(date = new Date()) {
+  fs.mkdirSync(OUTPUT_ROOT, { recursive: true });
+  const frameDirectory = assertOutputDirectorySafe(
+    path.join(OUTPUT_ROOT, `raw-frames-${timestampForDirectory(date)}`),
+  );
+  fs.mkdirSync(frameDirectory);
+  return frameDirectory;
+}
+
+function findDemoRpk(demoRpkDirectory = path.join(OUTPUT_ROOT, 'demo-rpk')) {
+  if (!fs.existsSync(demoRpkDirectory)) {
+    throw new Error(`Demo RPK directory does not exist: ${demoRpkDirectory}. Run npm run build:demo first.`);
+  }
+
+  const candidates = fs.readdirSync(demoRpkDirectory)
+    .map((name) => path.join(demoRpkDirectory, name))
+    .filter((candidate) => candidate.endsWith('.rpk'))
+    .filter((candidate) => fs.statSync(candidate).isFile() && fs.statSync(candidate).size > 0)
+    .sort((left, right) => fs.statSync(right).mtimeMs - fs.statSync(left).mtimeMs);
+
+  if (!candidates.length) {
+    throw new Error(`No non-empty demo RPK found in ${demoRpkDirectory}. Run npm run build:demo first.`);
+  }
+  return path.resolve(candidates[0]);
+}
+
+function decodePngDimensions(frame) {
+  const png = Buffer.from(frame);
+  const pngSignature = '89504e470d0a1a0a';
+  if (png.length < 24 || png.subarray(0, 8).toString('hex') !== pngSignature || png.toString('ascii', 12, 16) !== 'IHDR') {
+    throw new Error('Screenshot is not a decodable PNG with an IHDR chunk');
+  }
+  const width = png.readUInt32BE(16);
+  const height = png.readUInt32BE(20);
+  if (!width || !height) throw new Error('Screenshot PNG has empty dimensions');
+  return { width, height };
+}
+
+async function click(client, x, y) {
+  client.sendMouse({ x, y, buttons: 1 });
+  await wait(55);
+  client.sendMouse({ x, y, buttons: 0 });
+}
+
+async function setAcceleration(client, data) {
+  await new Promise((resolve, reject) => {
+    client.client.setSensor(
+      { target: 'ACCELERATION', value: { data } },
+      client.authMate,
+      (error) => (error ? reject(error) : resolve()),
+    );
+  });
+}
+
+async function executeEvent(client, event) {
+  if (event.kind === 'click') {
+    await click(client, event.x, event.y);
+  } else if (event.kind === 'acceleration') {
+    await setAcceleration(client, event.data);
+  } else {
+    throw new Error(`Unsupported capture event: ${event.kind}`);
+  }
+}
+
+async function waitForScreenshot(client, timeoutMilliseconds = 20000) {
+  const deadline = Date.now() + timeoutMilliseconds;
+  let lastError;
+  while (Date.now() <= deadline) {
+    try {
+      const frame = await client.getScreenshot();
+      if (frame && frame.length) return Buffer.from(frame);
+    } catch (error) {
+      lastError = error;
+    }
+    await wait(250);
+  }
+  const detail = lastError ? ` (${lastError.message || lastError})` : '';
+  throw new Error(`No non-empty screenshot received from ${VVD_NAME} within ${timeoutMilliseconds}ms${detail}`);
+}
+
+function createOfficialInstance(running) {
+  const serialPort = running['port.serial'];
+  if (!serialPort) throw new Error(`${VVD_NAME} is missing its emulator serial port registration`);
+  return findInstance(IMAGE_TYPE, { serialPort, vvdName: VVD_NAME });
+}
+
+async function installAndLaunch(instance, demoRpkPath) {
+  if (!instance || typeof instance.pushAndInstall !== 'function' || typeof instance.startApp !== 'function') {
+    throw new Error(`Official emulator instance for ${VVD_NAME} does not support install/launch operations`);
+  }
+  await instance.pushAndInstall(demoRpkPath, PACKAGE_NAME);
+  await instance.startApp(PACKAGE_NAME);
+}
+
+function disposeInstance(instance) {
+  instance?.disposeReadlines?.();
+  if (instance?.logcatProcess && !instance.logcatProcess.killed) instance.logcatProcess.kill();
+}
+
+async function captureSession(options = {}) {
+  const running = options.running || emulatorUtil.getRunningAvdConfigByName(VVD_NAME);
+  if (!running) throw new Error(`${VVD_NAME} is not running. Start the official VVD before running npm run capture:demo.`);
+
+  const demoRpkPath = options.demoRpkPath || findDemoRpk();
+  const frameDirectory = options.frameDirectory
+    ? assertOutputDirectorySafe(options.frameDirectory)
+    : createFreshFrameDirectory();
+  if (options.frameDirectory) fs.mkdirSync(frameDirectory, { recursive: false });
+
+  const instance = options.instance || createOfficialInstance(running);
+  const client = (options.createGrpcClient || createGrpcClient)(running);
+  const executedEvents = [];
+  try {
+    await installAndLaunch(instance, demoRpkPath);
+    await client.waitForReady();
+    let latestFrame = await waitForScreenshot(client, options.screenshotTimeoutMilliseconds);
+    const dimensions = decodePngDimensions(latestFrame);
+    await client.startStream((frame) => {
+      if (frame && frame.length) latestFrame = Buffer.from(frame);
+    });
+
+    const timeline = UI_EVENTS.slice().sort((left, right) => left.at - right.at);
+    const startedAt = Date.now();
+    let nextEvent = 0;
+    for (let frameNumber = 0; frameNumber < FRAME_COUNT; frameNumber += 1) {
+      const targetTime = frameNumber * (1000 / FPS);
+      while (nextEvent < timeline.length && timeline[nextEvent].at <= targetTime) {
+        const event = timeline[nextEvent];
+        await executeEvent(client, event);
+        executedEvents.push({ ...event, executedAt: Date.now() - startedAt });
+        nextEvent += 1;
+      }
+
+      if (!latestFrame.length) throw new Error(`Received an empty screenshot at frame ${frameNumber + 1}`);
+      fs.writeFileSync(
+        path.join(frameDirectory, `frame-${String(frameNumber + 1).padStart(4, '0')}.png`),
+        latestFrame,
+      );
+
+      const remaining = startedAt + targetTime + (1000 / FPS) - Date.now();
+      if (remaining > 0) await wait(remaining);
+    }
+
+    const manifest = {
+      vvdName: VVD_NAME,
+      imageType: IMAGE_TYPE,
+      fps: FPS,
+      durationSeconds: DURATION_SECONDS,
+      frames: FRAME_COUNT,
+      width: dimensions.width,
+      height: dimensions.height,
+      frameDirectory: path.resolve(frameDirectory),
+      events: executedEvents,
+    };
+    fs.writeFileSync(MANIFEST_PATH, `${JSON.stringify(manifest, null, 2)}\n`);
+    return manifest;
+  } finally {
+    client.close?.();
+    disposeInstance(instance);
+  }
+}
+
+async function main() {
+  const manifest = await captureSession();
+  console.log(JSON.stringify(manifest));
+}
+
+if (require.main === module) {
+  main().catch((error) => {
+    console.error(error.message || error);
+    process.exitCode = 1;
+  });
+}
+
+module.exports = {
+  VVD_NAME,
+  IMAGE_TYPE,
+  PACKAGE_NAME,
+  FPS,
+  DURATION_SECONDS,
+  FRAME_COUNT,
+  OUTPUT_ROOT,
+  MANIFEST_PATH,
+  UI_EVENTS,
+  assertOutputDirectorySafe,
+  timestampForDirectory,
+  createFreshFrameDirectory,
+  findDemoRpk,
+  decodePngDimensions,
+  click,
+  setAcceleration,
+  executeEvent,
+  waitForScreenshot,
+  createOfficialInstance,
+  installAndLaunch,
+  captureSession,
+};
